def transform(grid):
    # Mark the 2x2 objects belonging to the diagonal chain that begins at
    # the top-left object and proceeds down/right by touching corners.
    h, w = len(grid), len(grid[0])
    seen=[]
    for r in range(h-1):
        for c in range(w-1):
            if all(grid[y][x]==2 for y in (r,r+1) for x in (c,c+1)):
                if not any((r,c)==p for p in seen): seen.append((r,c))
    # Four-neighbor component groups of exact 2x2 blocks, linking diagonally
    # when their corners touch (offset 2,2).
    links={p:set() for p in seen}
    for a in seen:
        for b in seen:
            if a!=b and max(abs(a[0]-b[0]),abs(a[1]-b[1]))<=2:
                links[a].add(b)
    # color components having at least three blocks
    out=[row[:] for row in grid]
    unseen=set(seen)
    while unseen:
        start=unseen.pop(); comp={start}; stack=[start]
        while stack:
            p=stack.pop()
            for q in links[p]&unseen:
                unseen.remove(q); comp.add(q); stack.append(q)
        if len(comp)>=3:
            for r,c in comp:
                for y in (r,r+1):
                    for x in (c,c+1): out[y][x]=8
    return out
