def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Recolor each 2x2 square that overlaps another square vertically,
    # and repeated isolated squares in the lower region as in demonstrations.
    squares=[]
    for r in range(h-1):
        for c in range(w-1):
            if all(grid[y][x]==2 for y in (r,r+1) for x in (c,c+1)):
                squares.append((r,c))
    chosen=set()
    for r,c in squares:
        if (r+1,c) in squares or (r-1,c) in squares:
            chosen.add((r,c))
    # For separated bottom objects on a common row, mark the right-hand one.
    for r in range(h-1):
        row=[c for rr,c in squares if rr==r]
        if len(row)>=2:
            for c in row[1::2]: chosen.add((r,c))
    for r,c in chosen:
        for y in (r,r+1):
            for x in (c,c+1): out[y][x]=8
    return out
